// energy/degradation sketch for: Fusion Plant Digital Engineering Tool
let c = 1.0; const samples = [];
for (let i = 0; i < 447; i++) { c *= 0.9996; if (i % 100 === 0) samples.push(+c.toFixed(4)); }
console.log(JSON.stringify({ cycles: 447, retention: +c.toFixed(4), samples: samples,
  eolReached: c < 0.8 }));

